use tokio_tungstenite::{client_async_with_config, connect_async, MaybeTlsStream, WebSocketStream};
use types::TxInfoWithConfirmation;

pub extern crate tokio_tungstenite;

pub type WsSubscription<T> = Result<BoxStream<'static, anyhow::Result<T>>, WsError>;

/// Message substring returned by the sequencer when it reached the configured stop height.
const STOP_HEIGHT_ERROR_MARKER: &[u8] = b"The preferred sequencer has reached the stop height ";
const HTTP_4XX_STATUS_MARKER: &[u8] = b"\"status\":4";

fn contains_subslice(haystack: &[u8], needle: &[u8]) -> bool {
    if needle.is_empty() {
        return true;
    }
    haystack
        .windows(needle.len())
        .any(|window| window == needle)
}

/// Checks whether an API client error indicates that the preferred sequencer reached stop height.
pub fn is_stop_height_error(err: &Error<types::ApiError>) -> bool {
    matches!(
        err,
        Error::ErrorResponse(response)
            if contains_subslice(response.message.as_bytes(), STOP_HEIGHT_ERROR_MARKER)
    )
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct WsMessage<T> {
    pub id: String,
    pub contents: T,
}

pub struct TxWsSender {
    sink: SplitSink<WebSocketStream<MaybeTlsStream<TcpStream>>, Message>,
}

impl TxWsSender {
    pub async fn send(&mut self, tx: &RawTx, id: String) -> Result<(), WsError> {
        let message = WsMessage {
            id: id.clone(),
            contents: types::AcceptTxBody {
                body: BASE64_STANDARD.encode(tx),
            },
        };
        self.sink
            .send(Message::Text(
                serde_json::to_string(&message).unwrap().into(),
            ))
            .await?;
        Ok(())
    }
}

progenitor::generate_api!(
    spec = "./openapi-v3.yaml",
    derives = [Debug, Clone, PartialEq],
);

/// Custom WebSocket extensions and extra utilities, in addition to the
/// [`Client`] generated by [`progenitor`].
impl Client {
    pub async fn subscribe_slots_with_children(
        &self,
        include_children: IncludeChildren,
    ) -> WsSubscription<types::Slot> {
        self.subscribe_to_ws(&format!(
            "/ledger/slots/latest/ws?children={include_children}"
        ))
        .await
    }

    pub async fn subscribe_slots(&self) -> WsSubscription<types::Slot> {
        self.subscribe_slots_with_children(IncludeChildren::default())
            .await
    }

    pub async fn subscribe_finalized_slots_with_children(
        &self,
        include_children: IncludeChildren,
    ) -> WsSubscription<types::Slot> {
        self.subscribe_to_ws(&format!(
            "/ledger/slots/finalized/ws?children={include_children}"
        ))
        .await
    }

    pub async fn subscribe_finalized_slots(&self) -> WsSubscription<types::Slot> {
        self.subscribe_finalized_slots_with_children(IncludeChildren::default())
            .await
    }

    pub async fn subscribe_aggregated_proof(&self) -> WsSubscription<types::AggregatedProof> {
        self.subscribe_to_ws("/ledger/aggregated-proofs/latest/ws")
            .await
    }

    pub async fn send_tx_to_sequencer<Tx: BorshSerialize>(
        &self,
        tx: &Tx,
    ) -> Result<ResponseValue<TxInfoWithConfirmation>, Error<types::ApiError>> {
        let tx_bytes = borsh::to_vec(tx).map_err(|err| Error::InvalidRequest(err.to_string()))?;
        let tx_b64 = BASE64_STANDARD.encode(&tx_bytes);
        self.accept_tx(&types::AcceptTxBody { body: tx_b64 }).await
    }

    pub async fn send_raw_tx_to_sequencer(
        &self,
        tx: &RawTx,
    ) -> Result<ResponseValue<TxInfoWithConfirmation>, Error<types::ApiError>> {
        let tx_b64 = BASE64_STANDARD.encode(tx);
        self.accept_tx(&types::AcceptTxBody { body: tx_b64 }).await
    }

    pub async fn send_tx_to_sequencer_with_retry<Tx: BorshSerialize>(
        &self,
        tx: &Tx,
    ) -> Result<ResponseValue<TxInfoWithConfirmation>, Error<types::ApiError>> {
        let raw_tx =
            RawTx::new(borsh::to_vec(tx).map_err(|err| Error::InvalidRequest(err.to_string()))?);
        self.send_raw_tx_to_sequencer_with_retry(&raw_tx).await
    }

    pub async fn send_raw_tx_to_sequencer_with_retry(
        &self,
        raw_tx: &RawTx,
    ) -> Result<ResponseValue<TxInfoWithConfirmation>, Error<types::ApiError>> {
        let tx_b64 = BASE64_STANDARD.encode(raw_tx);
        let backoff = ExponentialBuilder::default()
            .with_factor(1.5)
            .with_min_delay(Duration::from_millis(200))
            .with_max_times(30)
            // With max delay of 15 seconds, the maximal total waiting time is going to be a little bit more than 5 minutes
            .with_max_delay(Duration::from_secs(15));
        let tx = types::AcceptTxBody { body: tx_b64 };
        let client = self.clone();
        let fut = || async { client.accept_tx(&tx).await };
        fut.retry(backoff)
            .when(|err| {
                match err {
                    Error::InvalidRequest(_) | Error::InvalidUpgrade(_) | Error::PreHookError(_) => false,
                    Error::ErrorResponse(_) => !is_stop_height_error(err),
                    Error::CommunicationError(_) | Error::ResponseBodyError(_) | Error::UnexpectedResponse(_) => true,
                    // This needs further improvement on the generated client.
                    // Details in https://github.com/Sovereign-Labs/sovereign-sdk-wip/pull/2799
                    Error::InvalidResponsePayload(bytes, _error) => {
                        let response_body = bytes.as_ref();
                        // We don't retry HTTP 4** errors, and we don't retry "reached the stop
                        // height" errors since that means the rollup has shut down.
                        let is_non_retryable = contains_subslice(
                            response_body,
                            STOP_HEIGHT_ERROR_MARKER,
                        ) || contains_subslice(response_body, HTTP_4XX_STATUS_MARKER);
                        !is_non_retryable
                    }
                }
            })
            .notify(|err, dur| {
                tracing::warn!(err = ?err, duration = ?dur, "Failed to submit transaction. Retrying...");
            })
            .await
    }

    /// Sends transactions to the sequencer for later publication.
    pub async fn send_txs_to_sequencer<Tx: BorshSerialize>(
        &self,
        txs: &[Tx],
    ) -> Result<Vec<ResponseValue<TxInfoWithConfirmation>>, Error<types::ApiError>> {
        let mut receipts = Vec::with_capacity(txs.len());

        for tx in txs {
            let res = self.send_tx_to_sequencer_with_retry(tx).await?;
            receipts.push(res);
        }

        Ok(receipts)
    }

    pub async fn subscribe_to_tx_status_updates(
        &self,
        tx_hash: TxHash,
    ) -> WsSubscription<types::TxInfo> {
        self.subscribe_to_ws(&format!("/sequencer/txs/{tx_hash}/ws"))
            .await
    }

    pub async fn subscribe_to_txs(
        &self,
        starting_from: Option<u64>,
    ) -> WsSubscription<types::ApiAcceptedTx> {
        let path = if let Some(starting_from) = starting_from {
            &format!("/sequencer/txs/ws?start_from={starting_from}")
        } else {
            "/sequencer/txs/ws"
        };
        self.subscribe_to_ws(path).await
    }

    pub async fn subscribe_to_events(&self) -> WsSubscription<types::LedgerEvent> {
        self.subscribe_to_ws("/sequencer/events/ws").await
    }

    pub async fn subscribe_to_events_with_config(
        &self,
        config: WebSocketConfig,
    ) -> WsSubscription<types::LedgerEvent> {
        self.subscribe_to_ws_with_config("/sequencer/events/ws", Some(config))
            .await
    }

    /// Subscribe to events with custom WebSocket and TCP socket configuration.
    ///
    /// This allows setting TCP-level options like `SO_RCVBUF` which control the actual
    /// TCP receive buffer size, enabling proper backpressure testing.
    pub async fn subscribe_to_events_with_socket_options(
        &self,
        ws_config: Option<WebSocketConfig>,
        recv_buffer_size: Option<u32>,
    ) -> WsSubscription<types::LedgerEvent> {
        self.subscribe_to_ws_with_socket_options(
            "/sequencer/events/ws",
            ws_config,
            recv_buffer_size,
        )
        .await
    }

    pub async fn subscribe_to_events_with_filter(
        &self,
        filter: &str,
    ) -> WsSubscription<types::LedgerEvent> {
        self.subscribe_to_ws(&format!("/sequencer/events/ws?key={filter}"))
            .await
    }

    pub async fn subscribe_to_ws<T: serde::de::DeserializeOwned>(
        &self,
        path: &str,
    ) -> WsSubscription<T> {
        self.subscribe_to_ws_with_socket_options(path, None, None)
            .await
    }

    pub async fn subscribe_to_ws_with_config<T: serde::de::DeserializeOwned>(
        &self,
        path: &str,
        config: Option<WebSocketConfig>,
    ) -> WsSubscription<T> {
        self.subscribe_to_ws_with_socket_options(path, config, None)
            .await
    }

    /// Subscribe to a WebSocket endpoint with custom WebSocket and TCP socket options.
    ///
    /// The `recv_buffer_size` parameter sets the TCP socket's `SO_RCVBUF` option,
    /// which controls the actual TCP receive buffer size. This enables proper
    /// backpressure testing by limiting how much data TCP can buffer before
    /// the sender blocks.
    pub async fn subscribe_to_ws_with_socket_options<T: serde::de::DeserializeOwned>(
        &self,
        path: &str,
        ws_config: Option<WebSocketConfig>,
        recv_buffer_size: Option<u32>,
    ) -> WsSubscription<T> {
        use std::net::ToSocketAddrs;
        use tokio_tungstenite::tungstenite::client::IntoClientRequest;

        // Build the WebSocket URL
        let ws_url = format!("{}{}", self.baseurl(), path).replace("http://", "ws://");

        // Parse host and port from baseurl for TCP connection
        // baseurl is like "http://127.0.0.1:12345"
        let base = self.baseurl();
        let without_scheme = base
            .strip_prefix("http://")
            .or_else(|| base.strip_prefix("https://"))
            .unwrap_or(base);
        let addr = without_scheme
            .to_socket_addrs()
            .map_err(WsError::Io)?
            .next()
            .ok_or_else(|| {
                WsError::Io(std::io::Error::new(
                    std::io::ErrorKind::AddrNotAvailable,
                    "Could not resolve address",
                ))
            })?;

        // Create TCP socket and set options
        let socket = if addr.is_ipv4() {
            TcpSocket::new_v4()
        } else {
            TcpSocket::new_v6()
        }
        .map_err(WsError::Io)?;

        if let Some(size) = recv_buffer_size {
            socket.set_recv_buffer_size(size).map_err(WsError::Io)?;
        }

        // Connect
        let stream = socket.connect(addr).await.map_err(WsError::Io)?;

        // Perform WebSocket handshake
        let request = ws_url.into_client_request()?;
        let (ws, _) = client_async_with_config(request, stream, ws_config).await?;

        Ok(ws
            .filter_map(|msg| async {
                match msg {
                    Ok(Message::Text(text)) => match serde_json::from_str(&text) {
                        Ok(tx_status) => Some(Ok(tx_status)),
                        Err(err) => Some(Err(anyhow::anyhow!(
                            "failed to deserialize JSON {} into type: {}",
                            text,
                            err
                        ))),
                    },
                    Ok(Message::Binary(data)) => {
                        // Parse binary frame as UTF-8 JSON
                        match std::str::from_utf8(&data) {
                            Ok(text) => match serde_json::from_str(text) {
                                Ok(tx_status) => Some(Ok(tx_status)),
                                Err(err) => Some(Err(anyhow::anyhow!(
                                    "failed to deserialize JSON from binary frame: {}",
                                    err
                                ))),
                            },
                            Err(err) => Some(Err(anyhow::anyhow!(
                                "invalid UTF-8 in binary WebSocket frame: {}",
                                err
                            ))),
                        }
                    }
                    // All other kinds of messages are ignored because
                    // `tokio-tungstenite` ought to handle all
                    // meta-communication messages (ping, pong, close) for us anyway.
                    Ok(_) => None,
                    // Errors are not handled here but passed to the caller.
                    Err(err) => Some(Err(anyhow::anyhow!("{}", err))),
                }
            })
            .boxed())
    }

    pub async fn connect_txs_ws(
        &self,
    ) -> Result<
        (
            TxWsSender,
            BoxStream<'static, anyhow::Result<WsMessage<types::ApiAcceptedTx>>>,
        ),
        anyhow::Error,
    > {
        let (sink, stream) = self.connect_to_ws("/sequencer/txs/submit/ws").await?;
        Ok((TxWsSender { sink }, stream))
    }

    pub async fn connect_to_ws<T: serde::de::DeserializeOwned>(
        &self,
        path: &str,
    ) -> Result<
        (
            SplitSink<WebSocketStream<MaybeTlsStream<TcpStream>>, Message>,
            BoxStream<'static, anyhow::Result<T>>,
        ),
        anyhow::Error,
    > {
        // The base URL can't be used for WebSocket connections; we need to
        // change the protocol.
        let url = format!("{}{}", self.baseurl(), path).replace("http://", "ws://");

        let (ws, _) = connect_async(url).await?;
        let (write, read) = ws.split();

        Ok((
            write,
            read.filter_map(|msg| async {
                match msg {
                    Ok(Message::Text(text)) => match serde_json::from_str(&text) {
                        Ok(tx_status) => Some(Ok(tx_status)),
                        Err(err) => Some(Err(anyhow::anyhow!(
                            "failed to deserialize JSON {} into type: {}",
                            text,
                            err
                        ))),
                    },
                    Ok(Message::Binary(data)) => {
                        // Parse binary frame as UTF-8 JSON
                        match std::str::from_utf8(&data) {
                            Ok(text) => match serde_json::from_str(text) {
                                Ok(tx_status) => Some(Ok(tx_status)),
                                Err(err) => Some(Err(anyhow::anyhow!(
                                    "failed to deserialize JSON from binary frame: {}",
                                    err
                                ))),
                            },
                            Err(err) => Some(Err(anyhow::anyhow!(
                                "invalid UTF-8 in binary WebSocket frame: {}",
                                err
                            ))),
                        }
                    }
                    // All other kinds of messages are ignored because
                    // `tokio-tungstenite` ought to handle all
                    // meta-communication messages (ping, pong, clonse) for us anyway.
                    Ok(_) => None,
                    // Errors are not handled here but passed to the caller.
                    Err(err) => Some(Err(anyhow::anyhow!("{}", err))),
                }
            })
            .boxed(),
        ))
    }

    pub async fn get_next_nonce(&self, credential_id: &CredentialId) -> anyhow::Result<u64> {
        tracing::trace!(%credential_id, "Dedup is requested.");
        let param = types::Hash::from_str(&credential_id.to_string())?;
        let response = self.credential_id_dedup(&param).await?;
        let inner = match response.into_inner() {
            AnyJsonValue::Object(map) => map,
            other => {
                anyhow::bail!(
                    "Unexpected response shape is returned from dedup endpoint: {other:?}"
                )
            }
        };
        inner
            .get("nonce")
            .and_then(|nonce| nonce.as_u64())
            .ok_or(anyhow::anyhow!("Failed to get nonce from {inner:?}"))
    }
}

impl TryInto<aggregated_proof::SerializedAggregatedProof> for types::AggregatedProof {
    type Error = anyhow::Error;

    fn try_into(self) -> anyhow::Result<aggregated_proof::SerializedAggregatedProof> {
        Ok(aggregated_proof::SerializedAggregatedProof {
            raw_aggregated_proof: decode_b64(&self.proof)?,
        })
    }
}

fn decode_b64(data: &str) -> anyhow::Result<Vec<u8>> {
    BASE64_STANDARD
        .decode(data)
        .context("Failed to decode base64 data in aggregated proof response")
}

impl From<types::SlotFinalityStatus> for FinalityStatus {
    fn from(value: types::SlotFinalityStatus) -> Self {
        match value {
            types::SlotFinalityStatus::Finalized => FinalityStatus::Finalized,
            types::SlotFinalityStatus::Pending => FinalityStatus::Pending,
        }
    }
}

impl From<TxHash> for types::TxHash {
    fn from(value: TxHash) -> Self {
        types::TxHash::from_str(&value.to_string()).unwrap()
    }
}
